#!/usr/bin/env python3
"""Read-only observations of the Trellis revision Mantle imports (task I2).

Writes one JSON object to stdout. It never writes to the Trellis checkout: it
uses `git show`/`ls-tree`/`rev-parse`, `git --no-optional-locks status`, and a
network fetch into a throwaway bare repository. The import check writes only to
a scratch directory it removes.
"""
import json
import pathlib
import subprocess
import sys
import tempfile
from datetime import datetime, timezone

TRELLIS = pathlib.Path("/home/brittonr/git/OnixResearch/trellis")
REMOTE = "git@github.com:OnixResearch/trellis.git"
MANTLE = pathlib.Path(sys.argv[1]).resolve()
PIN = "d91188e495d65bca87551b7a06330efb2c909edf"
SPEC = ".cairn/specs/fenced-attempt-admission/spec.md"
PUBLISHED = {
    "origin/main": "origin/main",
    "drain/fenced-attempt-admission-20260903": "8de4b24aa2d66cc2e6ec966d686df023492265d3",
    "cairn/add-fenced-attempt-admission-primitives": "26ef22128296d2b5535aaa0cb4229291c85fb8ee",
}


def run(argv, cwd=None, stdin=None, check=False):
    p = subprocess.run(argv, cwd=cwd, input=stdin, capture_output=True)
    if check and p.returncode:
        raise RuntimeError(f"{argv}: {p.stderr.decode(errors='replace')}")
    return p


def git(*args, check=True):
    return run(["git", "--no-optional-locks", "-C", str(TRELLIS), *args], check=check)


def text(p):
    return p.stdout.decode("utf-8", "replace").strip()


def b3(data):
    return run(["b3sum", "--no-names"], stdin=data, check=True).stdout.decode().strip()


def blob(rev, path):
    p = git("show", f"{rev}:{path}", check=False)
    return p.stdout if p.returncode == 0 else None


def req_ids(data):
    return sorted(line.split("]")[0][2:] for line in data.decode().splitlines() if line.startswith("r["))


out = {"schema": "mantle-trellis-pin-observations-v1", "observed_at_utc": datetime.now(timezone.utc).isoformat()}
out["mantle"] = {
    "head": text(run(["git", "-C", str(MANTLE), "rev-parse", "HEAD"], check=True)),
    "tracked_dirty_paths": len([l for l in text(run(["git", "-C", str(MANTLE), "status", "--porcelain", "--untracked-files=no"])).splitlines() if l]),
}
out["trellis_checkout"] = {
    "head": text(git("rev-parse", "HEAD")),
    "origin_main_tracking_ref": text(git("rev-parse", "origin/main")),
    "dirty_or_untracked_paths": len([l for l in text(git("status", "--short")).splitlines() if l]),
    "head_is_ancestor_of_origin_main": git("merge-base", "--is-ancestor", "HEAD", "origin/main", check=False).returncode == 0,
}

pin = {"revision": PIN, "object_type": text(git("cat-file", "-t", PIN))}
pin["commit"] = text(git("log", "-1", "--format=%H|%ad|%s", "--date=iso-strict", PIN))
pin["is_ancestor_of_origin_main_tracking_ref"] = git("merge-base", "--is-ancestor", PIN, "origin/main", check=False).returncode == 0
pin["local_branches_containing"] = [l.strip(" *") for l in text(git("branch", "--contains", PIN)).splitlines()]
pin["remote_tracking_branches_containing"] = [l.strip() for l in text(git("branch", "-r", "--contains", PIN)).splitlines()]
out["pin"] = pin

with tempfile.TemporaryDirectory(dir=str(MANTLE.parent / "tmp")) as probe:
    run(["git", "init", "-q", "--bare", probe], check=True)
    fetch = run(["timeout", "90", "git", "-C", probe, "fetch", "--quiet", "--depth=1", REMOTE, PIN])
    out["remote_availability"] = {
        "command": f"git fetch --depth=1 {REMOTE} {PIN} (into a throwaway bare repository)",
        "exit_code": fetch.returncode,
        "stderr": fetch.stderr.decode("utf-8", "replace").strip(),
        "object_present_after": run(["git", "-C", probe, "cat-file", "-e", PIN]).returncode == 0,
    }
out["remote_heads"] = {
    name: text(run(["timeout", "30", "git", "ls-remote", REMOTE, f"refs/heads/{name}"])).split("\t")[0]
    for name in ("main", "drain/fenced-attempt-admission-20260903", "cairn/add-fenced-attempt-admission-primitives")
}

upstream = json.loads((MANTLE / "vendor/trellis-fenced-attempt/upstream.json").read_text())
out["mantle_pin_manifest"] = upstream
out["pinned_members_at_published_revisions"] = {
    label: {member: ("absent" if blob(rev, member) is None else ("MATCH" if b3(blob(rev, member)) == meta["blake3"] else "differs"))
            for member, meta in upstream["files"].items()}
    for label, rev in {"pin": PIN, **PUBLISHED}.items()
}

pin_spec, pub_spec = blob(PIN, SPEC), blob("origin/main", SPEC)
pin_lines, pub_lines = pin_spec.decode().splitlines(), pub_spec.decode().splitlines()
out["accepted_spec"] = {
    "path": SPEC,
    "blake3_at_pin": b3(pin_spec),
    "blake3_at_origin_main": b3(pub_spec),
    "requirement_ids_at_pin": req_ids(pin_spec),
    "requirement_ids_at_origin_main": req_ids(pub_spec),
    "lines_only_in_pin": [l for l in pin_lines if l not in pub_lines],
    "lines_only_in_origin_main": [l for l in pub_lines if l not in pin_lines],
}
archive = "2026-09-03-add-fenced-attempt-admission-primitives"
out["accepted_change"] = {
    "archive_dir": f".cairn/archive/{archive}",
    "archive_present_at_origin_main": git("cat-file", "-e", f"origin/main:.cairn/archive/{archive}/proposal.md", check=False).returncode == 0,
    "archive_commit": text(git("log", "--diff-filter=A", "--format=%H|%ad|%s", "--date=short", "origin/main", "--", f".cairn/archive/{archive}/proposal.md")),
    "focused_verus_log": (blob("origin/main", f".cairn/archive/{archive}/evidence/final-2026-09-03/focused-verus.log") or b"").decode().strip(),
    "full_verify_last_line": (blob("origin/main", f".cairn/archive/{archive}/evidence/final-2026-09-03/full-verify.log") or b"").decode().strip().splitlines()[-1:],
}

lock = json.loads(blob(PIN, "flake.lock"))
nodes = lock["nodes"]
def locked(name):
    l = nodes[name]["locked"]
    return {k: l.get(k) for k in ("type", "owner", "repo", "rev", "narHash")}
flake_nix = (blob(PIN, "flake.nix") or b"").decode().splitlines()
out["toolchain_at_pin"] = {
    "vstd": next((l.strip() for l in (blob(PIN, "Cargo.toml") or b"").decode().splitlines() if l.strip().startswith("vstd")), None),
    "rust_toolchain_toml": (blob(PIN, "rust-toolchain.toml") or b"").decode().strip(),
    "verus_script_blake3": b3(blob(PIN, "scripts/verus.sh")),
    "verus_script_provider_lines": [l.strip() for l in blob(PIN, "scripts/verus.sh").decode().splitlines() if "octet" in l.lower() or ".#verus" in l][:6],
    "flake_nix_verus_lines": [l.strip() for l in flake_nix if "verus" in l.lower() and "octet" in l.lower()][:6],
    "flake_lock_octet": locked("octet"),
    "flake_lock_octet_aeneas": locked("octet-aeneas"),
    "flake_lock_root_rust_overlay": locked(nodes[lock["root"]]["inputs"]["rust-overlay"]) if "rust-overlay" in nodes[lock["root"]]["inputs"] else None,
}

bundle = json.loads(blob(PIN, "docs/proof-evidence-bundle.json"))
record = next(r for r in bundle["records"] if r["scope"] == "module:fenced_attempt_admission::verified")
out["exported_artifact_at_pin"] = {
    "contract_file": "json-artifacts/proof-evidence-bundle.ncl",
    "contract_file_text": blob(PIN, "json-artifacts/proof-evidence-bundle.ncl").decode().strip(),
    "bundle_path": "docs/proof-evidence-bundle.json",
    "bundle_blake3": b3(blob(PIN, "docs/proof-evidence-bundle.json")),
    "bundle_schema_version": bundle["schema_version"],
    "bundle_generated_by": bundle["generated_by"],
    "record": record,
}

with tempfile.TemporaryDirectory(dir=str(MANTLE.parent / "tmp")) as scratch:
    check = run([sys.executable, "scripts/import-trellis-fenced-attempt.py", "--check"], cwd=MANTLE)
    imported = pathlib.Path(scratch) / "imported"
    imp = run([sys.executable, "scripts/import-trellis-fenced-attempt.py", "--repository", str(TRELLIS), "--out", str(imported)], cwd=MANTLE)
    diff = run(["diff", "-r", str(imported), str(MANTLE / "vendor/trellis-fenced-attempt")])
    out["mantle_vendored_copy"] = {
        "offline_check": {"exit_code": check.returncode, "stdout": check.stdout.decode().strip(), "stderr": check.stderr.decode().strip()},
        "import_from_trellis_object_store": {"exit_code": imp.returncode, "stdout": imp.stdout.decode().strip(), "stderr": imp.stderr.decode().strip()},
        "diff_recursive_imported_vs_vendored": {"exit_code": diff.returncode, "stdout": diff.stdout.decode().strip()},
    }
print(json.dumps(out, indent=1, sort_keys=True))
